import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import fs from 'fs';
import { createScene } from './object.js';

// Create the scene
const root = createScene();

// Update all world matrices
root.updateMatrixWorld(true);

// Create a rotation matrix for -90 degrees around X axis (Y-up to Z-up for Blender)
const rotationMatrix = new THREE.Matrix4();
rotationMatrix.makeRotationX(-Math.PI / 2);

// Create a group to hold all transformed geometry for export
const exportGroup = new THREE.Group();

// Traverse all meshes and bake world transforms into geometry
root.traverse((obj) => {
  if (obj instanceof THREE.Mesh) {
    // Handle InstancedMesh separately
    if (obj instanceof THREE.InstancedMesh) {
      const instanceMatrix = new THREE.Matrix4();
      for (let i = 0; i < obj.count; i++) {
        // Clone the geometry for each instance
        const geom = obj.geometry.clone();

        // Get instance matrix
        obj.getMatrixAt(i, instanceMatrix);

        // Combine: world matrix * instance matrix
        const combinedMatrix = new THREE.Matrix4();
        combinedMatrix.multiplyMatrices(obj.matrixWorld, instanceMatrix);

        // Apply Blender rotation
        combinedMatrix.premultiply(rotationMatrix);

        // Apply to geometry
        geom.applyMatrix4(combinedMatrix);

        // Create mesh for export
        const exportMesh = new THREE.Mesh(geom);
        exportMesh.name = `${obj.name}_instance_${i}`;
        exportGroup.add(exportMesh);
      }
    } else {
      // Regular mesh: clone geometry and apply world transform
      const geom = obj.geometry.clone();

      // Create combined matrix with Blender rotation
      const combinedMatrix = new THREE.Matrix4();
      combinedMatrix.multiplyMatrices(rotationMatrix, obj.matrixWorld);

      // Apply to geometry
      geom.applyMatrix4(combinedMatrix);

      // Create mesh for export
      const exportMesh = new THREE.Mesh(geom);
      exportMesh.name = obj.name;
      exportGroup.add(exportMesh);
    }
  }
});

// Export to OBJ
const exporter = new OBJExporter();
const objString = exporter.parse(exportGroup);

// Write to file
fs.writeFileSync('/root/output/object.obj', objString);

console.log('Exported to /root/output/object.obj');

